func counterStream() -> AsyncStream<Int> {
    AsyncStream {
        continuation in
        for i in 1...3 {
            continuation.yield(i)
        }
        continuation.finish()
    }
}

func sum() async {
    var total = 0
    for await num in counterStream() {
        total += num
    }
    print("Total: \(total)")
}
await sum()

