struct StepCounter: AsyncSequence, AsyncIteratorProtocol {
    typealias Element = Int
    var count = 0
    mutating func next() async -> Int? {
        if count < 2 {
            count += 1
            return count * 10
        }
        return nil
    }
    func makeAsyncIterator() -> StepCounter { self }
}

func run() async {
    var results: [Int] = []
    for await val in StepCounter() {
        results.append(val)
    }
    print(results)
}
await run()

func streamPrefix() async {
    let stream = AsyncStream<Int> {
        continuation in
        for i in 1...5 { continuation.yield(i) }
        continuation.finish()
    }
    var sum = 0
    for await x in stream.prefix(2) {
        sum += x
    }
    print("Prefix sum: \(sum)")
}
await streamPrefix()

func filterStream() async {
    let stream = AsyncStream<Int> {
        continuation in
        continuation.yield(1)
        continuation.yield(4)
        continuation.yield(7)
        continuation.finish()
    }
    var evens: [Int] = []
    for await n in stream.filter({ $0 % 2 == 0 }) {
        evens.append(n)
    }
    print(evens)
}
await filterStream()

