func earlyBreak() async {
    let stream = AsyncStream<Int> {
        continuation in
        continuation.yield(100)
        continuation.yield(200)
        continuation.yield(300)
        continuation.finish()
    }
    var first = 0
    for await val in stream {
        first = val
        break
    }
    print("First: \(first)")
}
await earlyBreak()

