func sumEvenNumbers() async -> Int {
    let stream = AsyncStream<Int> {
        continuation in
        for n in 1...5 {
            continuation.yield(n)
        }
        continuation.finish()
    }
    var sum = 0
    for await val in stream {
        if val % 2 == 0 {
            sum += val
        }
    }
    return sum
}
let total = await sumEvenNumbers()
print("Even sum: \(total)")

